  "Modules unlock in order. Read each module, then pass its knowledge check with at least 80%.": {
    "rw": "Ibice by’isomo bifunguka bikurikiranye. Soma buri gice, hanyuma utsinde isuzuma ryacyo n’amanota nibura 80%.",
    "fr": "Les modules se déverrouillent dans l'ordre. Lisez chaque module, puis réussissez son contrôle de connaissances avec au moins 80 %."
  },
  "Quizzes and the exam are timed by the server. The timer cannot be paused, and only answers saved before time runs out are graded.": {
    "rw": "Seriveri igenzura igihe cy’amasuzuma n’ikizamini. Igihe ntigishobora guhagarikwa; ibisubizo bibitswe mbere y’uko igihe kirangira ni byo byonyine bitangirwa amanota.",
    "fr": "Les quiz et l'examen sont chronométrés par le serveur. Le chronomètre ne peut pas être mis en pause et seules les réponses enregistrées avant la fin du temps imparti sont notées."
  },
  "Quizzes and exams are proctored: your camera must stay on, the assessment opens in full screen, and you cannot leave the page until you submit. The camera feed is not recorded.": {
    "rw": "Amasuzuma n’ibizamini biracungwa: kamera igomba kuguma ifunguye, isuzuma rigafata ecran yose kandi ntushobora kuva ku rupapuro utaratanga ibisubizo. Amashusho ya kamera ntabikwa.",
    "fr": "Les quiz et examens sont surveillés : votre caméra doit rester allumée, l'évaluation s'ouvre en plein écran et vous ne pouvez pas quitter la page tant que vous n'avez pas soumis. Le flux de la caméra n’est pas enregistré."
  },
  "Leaving the tab, leaving full screen or turning off the camera is recorded. After": {
    "rw": "Kuva kuri tab, kuva kuri ecran yuzuye cyangwa gufunga kamera birandikwa. Nyuma yo kubikora",
    "fr": "La sortie de l'onglet, la sortie du plein écran ou l'extinction de la caméra sont enregistrées. Après"
  },
