  "Approved trainers publish courses from their studio once every requirement is met. They appear here as soon as they go live.": {
    "rw": "Abatoza bemejwe batangaza amasomo mu gice cyabo cyo kuyategura iyo ibisabwa byose byujujwe. Amasomo ahita agaragara hano akimara gutangazwa.",
    "fr": "Les formateurs agréés publient les cours depuis leur studio une fois que toutes les exigences sont remplies. Ils apparaissent ici dès leur mise en ligne."
  },
  "Plan outcomes, write module readings, add a knowledge check to each module, set a final exam, then submit for publication.": {
    "rw": "Teganya intego z’imyigire, wandike ibice by’isomo, wongeremo isuzuma muri buri gice, utegure ikizamini gisoza, hanyuma wohereze kugira ngo bitangazwe.",
    "fr": "Planifier les résultats, rédiger les lectures des modules, ajouter une vérification des connaissances à chaque module, organiser un examen final, puis soumettre pour publication."
  },
