  "Activities, meetings, certificates, and member records stay traceable from school level to national office.": {
    "rw": "Ibikorwa, amanama, ibyemezo, hamwe ninyandiko zabanyamuryango bikomeza gukurikiranwa kuva kurwego rwishuri kugeza ku biro byigihugu.",
    "fr": "Les activités, réunions, certificats et dossiers des membres restent traçables du niveau de l'école au bureau national."
  },
