  "21 September 1962": {
    "rw": "21 Nzeri 1962",
    "fr": "21 septembre 1962"
  },
  "Rwanda became an independent state on 1 July 1962. Learning the chronology of its history helps us understand the country’s journey.": {
    "rw": "U Rwanda rwabonye ubwigenge ku wa 1 Nyakanga 1962. Kwiga uko amateka yarwo yagiye akurikirana bidufasha kumva urugendo rw’igihugu.",
    "fr": "Le Rwanda est devenu indépendant le 1 juillet 1962. Étudier la chronologie de son histoire aide à comprendre le parcours du pays."
  },
